{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/research_contract.py; cloud_pilot/live/stages.py",
      "detail": "A source classified CONTEXT_ONLY can still support an allowed core vehicle identity or specification fact. The validation rejects MISMATCH, but does not require MATCHED for T2 sources used by core facts. The independent acceptance check requires a T1/T2 tier and an applicability assertion, but does not enforce the source's scope classification. Consequently, a context-only source can help authorize writing of a reference-vehicle claim despite the source-scope gate.",
      "required_fix": "Require sources credited with supporting core vehicle identity and specifications to have scope_status=MATCHED, both during proposal validation and independent acceptance. Add regression tests covering CONTEXT_ONLY T2 identity and non-identity specification claims, while retaining accurately scoped contextual background."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
